int configure_usb_console(struct console *co, char *options) {
    int baud_rate = 0;
    int data_bits = 0;
    char parity = '\0';
    int flow_control = 0;
    int ret = 0;
    char *token = NULL;

    if (!co || !options) {
        return -1;
    }

    token = strtok(options, ",");
    while (token != NULL) {
        if (strncmp(token, "baud=", 5) == 0) {
            baud_rate = atoi(token + 5);
        } else if (strncmp(token, "bits=", 5) == 0) {
            data_bits = atoi(token + 5);
        } else if (strncmp(token, "parity=", 7) == 0) {
            parity = token[7];
        } else if (strncmp(token, "flow=", 5) == 0) {
            flow_control = atoi(token + 5);
        }
        token = strtok(NULL, ",");
    }

    if (baud_rate <= 0 || data_bits <= 0 || (parity != 'n' && parity != 'o' && parity != 'e')) {
        return -1;
    }

    struct usb_serial *port = get_usb_serial_port(co->index);
    if (!port) {
        return -2;
    }

    if (port->state != USB_SERIAL_CONNECTED) {
        log_error("USB serial port is not connected.");
        return -3;
    }

    ret = open_usb_serial_port(port);
    if (ret < 0) {
        return ret;
    }

    ret = configure_usb_serial_port(port, baud_rate, data_bits, parity, flow_control);
    if (ret < 0) {
        close_usb_serial_port(port);
        return ret;
    }

    co->configured = 1;
    co->is_system_console = 1;

    return 0;
}
